package com.ute.uteexpress.operations;

import com.ute.uteexpress.dto.admin.*;
import com.ute.uteexpress.dto.admin.ReportViews.*;
import com.ute.uteexpress.dto.admin.ReportViews.Period;
import com.ute.uteexpress.dto.operations.OperationsDashboardViews;
import com.ute.uteexpress.entity.*;
import com.ute.uteexpress.enums.*;
import com.ute.uteexpress.service.*;
import com.ute.uteexpress.service.reports.*;
import com.ute.uteexpress.repository.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import static com.ute.uteexpress.operations.OperationsJdbcFixture.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual aggregate/scalar/UNION queries on Hibernate/H2 JDBC. Never SQL Server or a mock aggregate model. */
@SpringJUnitConfig(AdminReportingJdbcConfig.class)
class AdminReportingJdbcTests extends OperationsJdbcSupport {
    @Autowired AdminReportService reports;@Autowired AdminAuditService audit;@Autowired AdminUserService adminUsers;@Autowired AuditLogRepository auditRows;
    @Autowired ReportCsvService csv;@Autowired ReportPolicy policy;
    @BeforeEach void admin(){as(f.admin,"ROLE_ADMIN");}
    Request request(Dataset d){return new Request(d,Period.TODAY,null,null,null,null,null,Trend.DAY);}
    Dashboard report(Dataset d){return reports.read(request(d),0,20);}
    long count(Dataset d){return report(d).details().total();}
    AuditViews.Request auditRequest(){return new AuditViews.Request(Period.TODAY,null,null,AuditViews.Source.ALL,null,null,null,null,null);}
    @ParameterizedTest @EnumSource(Dataset.class)
    void allReportQueriesAndCsvShapesExecuteOnJdbcWithEmptyData(Dataset dataset){var view=report(dataset);assertNotNull(view);assertTrue(view.metrics().stream().noneMatch(m->m.value().contains("NaN")));assertNotNull(csv.export(request(dataset),Export.SUMMARY));assertNotNull(csv.export(request(dataset),Export.DETAILS));}
    @Test void cohortUsesHalfOpenUtcDateAndStableIdOrder(){
        var day=NOW.toLocalDate().atStartOfDay();db(()->{f.shipment(f.source,f.destination,ShipmentStatus.CREATED,day.minusNanos(100));f.shipment(f.source,f.destination,ShipmentStatus.CREATED,day);f.shipment(f.source,f.destination,ShipmentStatus.CONFIRMED,day.plusDays(1).minusNanos(100));f.shipment(f.source,f.destination,ShipmentStatus.CREATED,day.plusDays(1));return null;});
        var view=report(Dataset.SHIPMENTS);assertEquals(2,view.details().total());assertEquals(2,view.trend().stream().mapToLong(Bar::value).sum());assertEquals(2,view.breakdowns().getFirst().rows().stream().mapToLong(Bar::value).sum());assertTrue(Long.parseLong(view.details().rows().get(0).get(0))>Long.parseLong(view.details().rows().get(1).get(0)));
    }
    @Test void databaseStatusBranchAndServiceFiltersApplyToRowsAndCsv(){db(()->{f.shipment(f.source,f.destination,ShipmentStatus.CREATED,NOW);f.shipment(f.foreign,f.destination,ShipmentStatus.CONFIRMED,NOW);return null;});var filter=new Request(Dataset.SHIPMENTS,Period.TODAY,null,null,f.foreign.getId(),f.catalog.getId(),"CONFIRMED",Trend.DAY);var view=reports.read(filter,0,20);assertEquals(1,view.details().total());String file=new String(csv.export(filter,Export.DETAILS).bytes(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(file.contains(view.details().rows().getFirst().get(1)));assertFalse(file.contains("\"SOURCE\""));}
    @Test void periodFiltersAreBoundedAndIncludeEndDay(){var today=NOW.toLocalDate();var f1=policy.filter(new Request(Dataset.SHIPMENTS,Period.CUSTOM,today.minusDays(92),today,null,null,null,null));assertEquals(today.plusDays(1).atStartOfDay(),f1.to());assertThrows(AdminRuleException.class,()->policy.filter(new Request(Dataset.SHIPMENTS,Period.CUSTOM,today.minusDays(93),today,null,null,null,null)));assertThrows(AdminRuleException.class,()->policy.filter(new Request(Dataset.SHIPMENTS,Period.CUSTOM,today,today.minusDays(1),null,null,null,null)));assertThrows(AdminRuleException.class,()->policy.filter(new Request(Dataset.SHIPMENTS,Period.CUSTOM,today,today.plusDays(1),null,null,null,null)));assertThrows(AdminRuleException.class,()->policy.filter(new Request(Dataset.SHIPMENTS,Period.CUSTOM,null,null,null,null,null,null)));}
    @Test void quickPeriodsUseInjectedUtcClock(){assertEquals(NOW.toLocalDate().minusDays(6),policy.filter(new Request(null,Period.LAST_7_DAYS,null,null,null,null,null,null)).fromDate());assertEquals(NOW.toLocalDate().withDayOfMonth(1),policy.filter(new Request(null,Period.THIS_MONTH,null,null,null,null,null,null)).fromDate());clock.set(NOW.toLocalDate().atStartOfDay());assertEquals(NOW.toLocalDate(),policy.filter(request(Dataset.SHIPMENTS)).fromDate());}
    @Test void weeklyMonthlyTrendsRollUpOnlyBoundedDailyAggregates(){db(()->{f.shipment(f.source,f.destination,ShipmentStatus.CREATED,NOW.minusDays(1));f.shipment(f.source,f.destination,ShipmentStatus.CREATED,NOW);return null;});for(var trend:List.of(Trend.WEEK,Trend.MONTH)){var view=reports.read(new Request(Dataset.SHIPMENTS,Period.LAST_7_DAYS,null,null,null,null,null,trend),0,20);assertEquals(2,view.trend().stream().mapToLong(Bar::value).sum());}}
    @Test void invalidIdsStatusesAndPaginationAreRejected(){assertThrows(AdminRuleException.class,()->reports.read(new Request(null,Period.TODAY,null,null,99999L,null,null,null),0,20));assertThrows(AdminRuleException.class,()->reports.read(new Request(null,Period.TODAY,null,null,null,-1L,null,null),0,20));assertThrows(AdminRuleException.class,()->reports.read(new Request(Dataset.TRIPS,Period.TODAY,null,null,null,null,"DELIVERED",null),0,20));assertThrows(AdminRuleException.class,()->reports.read(request(Dataset.SHIPMENTS),-1,20));assertThrows(AdminRuleException.class,()->reports.read(request(Dataset.SHIPMENTS),0,51));}
    @ParameterizedTest @ValueSource(strings={"ROLE_USER","ROLE_MANAGER","ROLE_SHIPPER"})
    void otherAuthoritiesDoNotInheritAdmin(String role){as(f.admin,role);assertThrows(AccessDeniedException.class,()->report(Dataset.SHIPMENTS));assertThrows(AccessDeniedException.class,()->audit.read(auditRequest(),0,20));assertThrows(AccessDeniedException.class,()->csv.export(request(Dataset.SHIPMENTS),Export.DETAILS));}
    @ParameterizedTest @EnumSource(value=UserStatus.class,names={"LOCKED","UNVERIFIED"})
    void disabledAdminIsDeniedDespiteSessionAuthority(UserStatus status){db(()->{em.find(User.class,f.admin.getId()).setStatus(status);return null;});assertThrows(AccessDeniedException.class,()->report(Dataset.SHIPMENTS));assertThrows(AccessDeniedException.class,()->audit.read(auditRequest(),0,20));}
    @Test void revokedDatabaseAdminRoleIsDenied(){db(()->{em.createQuery("delete from UserRole r where r.user.id=:id").setParameter("id",f.admin.getId()).executeUpdate();return null;});assertThrows(AccessDeniedException.class,()->report(Dataset.SHIPMENTS));assertThrows(AccessDeniedException.class,()->csv.export(request(Dataset.SHIPMENTS),Export.SUMMARY));}
    @Test void deliveryAttemptsCountShipmentsSeparatelyAndUseSameRatioAsManager(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.DELIVERED,NOW.minusDays(10));var a=f.assignment(s,f.shipper);f.attempt(s,a,1,DeliveryAttemptStatus.FAILED,NOW.minusHours(3));f.attempt(s,a,2,DeliveryAttemptStatus.FAILED,NOW.minusHours(2));var success=f.attempt(s,a,3,DeliveryAttemptStatus.SUCCESS,NOW.minusHours(1));f.proof(s,a,success,NOW);return null;});var view=report(Dataset.DELIVERIES);assertEquals(3,view.details().total());assertEquals("1",view.metrics().get(1).value());assertTrue(view.metrics().stream().anyMatch(m->m.label().equals("Vận đơn có FAILED")&&m.value().equals("1")));assertTrue(view.metrics().stream().anyMatch(m->m.label().contains("Tỷ lệ")&&m.value().equals("33.33")));assertEquals(1,count(Dataset.DELIVERED));assertEquals(0,count(Dataset.SHIPMENTS));as(f.destinationManager,"ROLE_MANAGER");assertEquals(new java.math.BigDecimal("33.33"),dashboard.read(f.destination.getId(),OperationsDashboardViews.Period.TODAY,null,null,null,OperationsDashboardViews.WorkGroup.CONFIRM,0).deliverySuccessRate());}
    @Test void deliveredWithoutMatchingProofAndUnstartedFailuresDoNotCount(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.DELIVERED,NOW);var a=f.assignment(s,f.shipper);var attempt=f.attempt(s,a,1,DeliveryAttemptStatus.SUCCESS,NOW);var proof=f.proof(s,a,attempt,NOW);proof.setActor(f.manager);var failed=f.shipment(f.source,f.destination,ShipmentStatus.DELIVERY_FAILED,NOW);var fa=f.assignment(failed,f.shipper);var broken=f.attempt(failed,fa,1,DeliveryAttemptStatus.FAILED,NOW);broken.setStartedAt(null);broken.setAssignment(null);broken.setActor(null);broken.setFailureCode(null);return null;});assertEquals(0,count(Dataset.DELIVERED));assertEquals(0,count(Dataset.DELIVERIES));}
    @Test void noAttemptsShowsNaInsteadOfInventedZeroPercent(){assertTrue(report(Dataset.DELIVERIES).metrics().stream().anyMatch(m->m.label().contains("Tỷ lệ")&&m.value().equals("N/A")));}
    @Test void returnRequestIsNotReceiptAndSnapshotIncludesOldPending(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.RETURNING,NOW.minusDays(20));var r=new ReturnRequest();r.setShipment(s);r.setRequestedBy(f.destinationManager);r.setReason("PRIVATE RETURN REASON");r.setStage(ReturnStage.REQUESTED);r.setRequestedAt(NOW.minusDays(10));em.persist(r);return null;});assertEquals(0,count(Dataset.RETURN_REQUESTS));assertEquals(0,count(Dataset.RETURNED));assertEquals(1,count(Dataset.PENDING_RETURNS));assertFalse(report(Dataset.PENDING_RETURNS).toString().contains("PRIVATE RETURN REASON"));}
    @Test void completedReturnRequiresRealSourceReceipt(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.RETURNED,NOW.minusDays(2));s.setReturnedAt(NOW);var r=new ReturnRequest();r.setShipment(s);r.setRequestedBy(f.destinationManager);r.setReason("PRIVATE");r.setStage(ReturnStage.COMPLETED);r.setRequestedAt(NOW);r.setCompletedAt(NOW);em.persist(r);var receipt=new ReturnReceipt();receipt.setReturnRequest(r);receipt.setActor(f.manager);receipt.setEmployee(f.managerEmployee);receipt.setBranch(f.source);receipt.setRecipientType(ReturnRecipientType.SENDER);receipt.setRecipientName("PRIVATE SENDER");receipt.setReference("PRIVATE REF");receipt.setReceivedAt(NOW);em.persist(receipt);return null;});assertEquals(1,count(Dataset.RETURNED));assertEquals(0,count(Dataset.PENDING_RETURNS));String file=new String(csv.export(request(Dataset.RETURNED),Export.DETAILS).bytes(),java.nio.charset.StandardCharsets.UTF_8);assertFalse(file.contains("PRIVATE"));}
    @Test void branchReportSeparatesOriginDestinationAndCustodyWithoutAddingThem(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.AT_ORIGIN_BRANCH,NOW);f.intake(s,f.source,NOW);return null;});var rows=report(Dataset.BRANCHES).details().rows();var source=rows.stream().filter(r->r.get(1).equals("SOURCE")).findFirst().orElseThrow();var destination=rows.stream().filter(r->r.get(1).equals("DESTINATION")).findFirst().orElseThrow();assertEquals("1",source.get(3));assertEquals("0",source.get(4));assertEquals("1",source.get(5));assertEquals("1",source.get(6));assertEquals("1",source.get(7));assertEquals("1",destination.get(4));assertEquals(1,count(Dataset.SHIPMENTS));}
    @Test void currentSnapshotDoesNotPretendToBeEventsInPeriod(){db(()->{var s=f.shipment(f.source,f.destination,ShipmentStatus.CREATED,NOW.minusDays(10));SupportTicket t=new SupportTicket();t.setTicketCode("LEGACY");t.setUser(f.owner);t.setShipment(s);t.setSubject("PRIVATE SUBJECT");t.setContent("INTERNAL SECRET CONTENT");t.setCreatedAt(NOW.minusDays(10));em.persist(t);return null;});assertEquals(0,count(Dataset.TICKETS));assertEquals(1,count(Dataset.OPEN_TICKETS));assertFalse(report(Dataset.OPEN_TICKETS).toString().contains("PRIVATE SUBJECT"));assertFalse(report(Dataset.OPEN_TICKETS).toString().contains("INTERNAL SECRET CONTENT"));}
    @Test void readonlyReportsAuditAndExportsDoNotWriteOrRecalculateFees(){var id=db(()->f.shipment(f.source,f.destination,ShipmentStatus.CREATED,NOW).getId());var before=db(()->em.find(Shipment.class,id).getTotalFee());var stats=emf.unwrap(org.hibernate.engine.spi.SessionFactoryImplementor.class).getStatistics();stats.clear();report(Dataset.SHIPMENTS);audit.read(auditRequest(),0,20);csv.export(request(Dataset.SHIPMENTS),Export.DETAILS);assertEquals(0,stats.getEntityInsertCount());assertEquals(0,stats.getEntityUpdateCount());assertEquals(0,stats.getEntityDeleteCount());assertEquals(before,db(()->em.find(Shipment.class,id).getTotalFee()));assertEquals(0,notices.count());assertEquals(0,eventRows.count());}
    @Test void auditUnionFiltersAndPaginationPreserveUnknownActorAndNeverLoadPayload(){db(()->{for(int i=0;i<3;i++){AuditLog a=new AuditLog();a.setResourceType(AuditResourceType.USER);a.setResourceId("42");a.setAction("USER_LOCKED");a.setOldValue("PASSWORD TOKEN INTERNAL DO NOT SELECT");a.setNewValue("PRIVATE PII");a.setCreatedAt(NOW);if(i>0)a.setActor(f.admin);em.persist(a);}var s=f.shipment(f.source,f.destination,ShipmentStatus.CONFIRMED,NOW);var e=f.event(s,"PRIVATE TITLE",ShipmentStatus.CREATED,ShipmentStatus.CONFIRMED,NOW);e.setDescription("PRIVATE DESCRIPTION");return null;});var all=audit.read(auditRequest(),0,2);assertEquals(4,all.total());assertEquals(2,all.rows().size());assertFalse(all.toString().contains("PASSWORD"));var adminOnly=audit.read(new AuditViews.Request(Period.TODAY,null,null,AuditViews.Source.ADMIN,f.admin.getId(),"USER_LOCKED","USER","42",null),0,20);assertEquals(2,adminOnly.total());var branch=audit.read(new AuditViews.Request(Period.TODAY,null,null,null,null,null,null,null,f.source.getId()),0,20);assertEquals(1,branch.total());assertEquals("STATUS_CONFIRMED",branch.rows().getFirst().action());assertFalse(branch.toString().contains("PRIVATE"));var legacy=audit.read(new AuditViews.Request(Period.TODAY,null,null,AuditViews.Source.ADMIN,null,null,null,null,null),0,20).rows().stream().filter(r->r.actorId()==null).findFirst().orElseThrow();assertEquals("Không xác định (legacy)",legacy.actorLabel());}
    @Test void invalidAuditFiltersRejectInjectionAndArbitraryActorIdentifiers(){for(var action:List.of("x' OR 1=1","DROP;TABLE","a".repeat(101)))assertThrows(AdminRuleException.class,()->audit.read(new AuditViews.Request(Period.TODAY,null,null,null,null,action,null,null,null),0,20));assertThrows(AdminRuleException.class,()->audit.read(new AuditViews.Request(Period.TODAY,null,null,null,-1L,null,null,null,null),0,20));assertThrows(AdminRuleException.class,()->audit.read(new AuditViews.Request(Period.TODAY,null,null,null,null,null,"SECRETS",null,null),0,20));}
    @Test void adminStatusAuditIsAtomicUsesRealActorAndContainsOnlyMinimalState(){adminUsers.lock(f.owner.getId());assertEquals(1,auditRows.count());var row=auditRows.findAll().getFirst();assertEquals(f.admin.getId(),row.getActor().getId());assertEquals("USER_LOCKED",row.getAction());assertEquals("ACTIVE",row.getOldValue());assertEquals("LOCKED",row.getNewValue());assertNull(row.getActorUsername());assertNull(row.getIpAddress());assertEquals(NOW,row.getCreatedAt());assertEquals(0,notices.count());adminUsers.unlock(f.owner.getId());assertEquals(2,auditRows.count());}
    @Test void auditFailureRollsBackActualUserMutation(){db(()->{em.createNativeQuery("ALTER TABLE dbo.audit_logs ADD CONSTRAINT test_reject_admin CHECK (action <> 'USER_LOCKED')").executeUpdate();return null;});try{assertThrows(RuntimeException.class,()->adminUsers.lock(f.owner.getId()));assertEquals(UserStatus.ACTIVE,db(()->em.find(User.class,f.owner.getId()).getStatus()));assertEquals(0,auditRows.count());}finally{db(()->{em.createNativeQuery("ALTER TABLE dbo.audit_logs DROP CONSTRAINT test_reject_admin").executeUpdate();return null;});}}
    @Test void outerRollbackCannotCreateSuccessfulAudit(){assertThrows(IllegalStateException.class,()->db(()->{adminUsers.lock(f.owner.getId());throw new IllegalStateException("Synthetic rollback");}));assertEquals(0,auditRows.count());assertEquals(UserStatus.ACTIVE,db(()->em.find(User.class,f.owner.getId()).getStatus()));}
    @Test void roleAuditStoresOnlyChangedRoleIdsAndDoesNotInventNoopChange(){var form=new RoleUpdateForm();form.setRoleIds(List.of(f.roles.get("ROLE_USER").getId(),f.roles.get("ROLE_MANAGER").getId()));adminUsers.updateRoles(f.owner.getId(),form);assertEquals(1,auditRows.count());var a=auditRows.findAll().getFirst();assertEquals("USER_ROLES_CHANGED",a.getAction());assertTrue(a.getNewValue().startsWith("roleIds="));assertFalse(a.getNewValue().contains(f.owner.getEmail()));adminUsers.updateRoles(f.owner.getId(),form);assertEquals(1,auditRows.count());}
    @Test void roleAuditFailureRollsBackMembershipsAtomically(){var form=new RoleUpdateForm();form.setRoleIds(List.of(f.roles.get("ROLE_USER").getId(),f.roles.get("ROLE_MANAGER").getId()));db(()->{em.createNativeQuery("ALTER TABLE dbo.audit_logs ADD CONSTRAINT test_reject_roles CHECK (action <> 'USER_ROLES_CHANGED')").executeUpdate();return null;});try{assertThrows(RuntimeException.class,()->adminUsers.updateRoles(f.owner.getId(),form));assertEquals(List.of("ROLE_USER"),db(()->em.createQuery("select r.role.name from UserRole r where r.user.id=:id",String.class).setParameter("id",f.owner.getId()).getResultList()));assertEquals(0,auditRows.count());}finally{db(()->{em.createNativeQuery("ALTER TABLE dbo.audit_logs DROP CONSTRAINT test_reject_roles").executeUpdate();return null;});}}
    @Test void topOneHundredGroupingKeepsRemainderSoChartsAndTotalsAgree(){db(()->{for(int i=0;i<101;i++){var branch=f.branch("GROUP"+i,BranchType.LOCAL_BRANCH);f.shipment(branch,f.destination,ShipmentStatus.CREATED,NOW);}return null;});var view=report(Dataset.SHIPMENTS);var branches=view.breakdowns().stream().filter(b->b.title().equals("Chi nhánh nguồn")).findFirst().orElseThrow();assertEquals(101,view.details().total());assertEquals(101,branches.rows().stream().mapToLong(Bar::value).sum());assertTrue(branches.rows().stream().anyMatch(b->b.label().equals("Nhóm khác")&&b.value()==1));}
}
